import{_ as e,c as a,o as s,a2 as t}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"Module Route Cache","description":"","frontmatter":{"sidebarPos":13,"sidebarTitle":"Module Route Cache"},"headers":[],"relativePath":"guide/module-route-cache/index.md","filePath":"guide/module-route-cache/index.md","lastUpdated":1783604244000}'),i={name:"guide/module-route-cache/index.md"},r=t(`<h1 id="module-route-cache" tabindex="-1">Module Route Cache <a class="header-anchor" href="#module-route-cache" aria-label="Permalink to &quot;Module Route Cache&quot;">​</a></h1><p>Modularous caches admin panel data <strong>per module route</strong> — filter counts, paginated index queries, single records, form payloads, and formatted table rows. A <strong>relationship graph</strong> and <strong>relation tags</strong> keep dependent routes consistent when related models change.</p><p>This cache layer targets the <strong>admin CRUD stack</strong> (repositories and controllers). It does <strong>not</strong> automatically cache public CMS blade rendering; see <a href="./cms-public-pages">CMS Public Pages</a> for that gap and the recommended b2press strategy.</p><h2 id="in-this-section" tabindex="-1">In This Section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In This Section&quot;">​</a></h2><table><thead><tr><th>Page</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./overview">Overview</a></td><td>Architecture, data flow, key format, trait map</td></tr><tr><td><a href="./configuration">Configuration</a></td><td><code>modularous.cache</code> merge, app overrides, env vars</td></tr><tr><td><a href="./cache-types">Cache Types</a></td><td><code>counts</code>, <code>index</code>, <code>record</code>, <code>formItem</code>, <code>formattedItem</code>, response types</td></tr><tr><td><a href="./invalidation">Invalidation</a></td><td><code>CacheObserver</code>, graph, dependencies, relation tags</td></tr><tr><td><a href="./queue-observer">Queue Observer</a></td><td>Async invalidation/warmup jobs, env vars, workers</td></tr><tr><td><a href="./manual-purge">Manual Purge</a></td><td>Per-route manual purge config</td></tr><tr><td><a href="./admin-cache-actions">Admin Cache Actions</a></td><td>Superadmin purge/warm UI + API</td></tr><tr><td><a href="./warmup">Warmup</a></td><td><code>warmupByModel</code>, artisan warm commands</td></tr><tr><td><a href="./per-module-setup">Per-Module Setup</a></td><td><code>HasCaching</code> + config checklist</td></tr><tr><td><a href="./cms-public-pages">CMS Public Pages</a></td><td>Admin cache vs public CMS; b2press presentation + full-page plan</td></tr><tr><td><a href="./swr">SWR</a></td><td>Stale-while-revalidate and warm jobs</td></tr><tr><td><a href="./url-stale-resilience">URL Stale Resilience</a></td><td>File-primary URL cache</td></tr><tr><td><a href="./webhook-revalidate">Webhook Revalidate</a></td><td>HMAC webhook for external purge/warm</td></tr><tr><td><a href="./console-commands">Console Commands</a></td><td>Links to <code>guide/console/cache/</code> command reference</td></tr></tbody></table><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Ensure Redis is available (default driver)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MODULAROUS_RESOURCE_CACHE_ENABLED=true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MODULAROUS_RESOURCE_CACHE_DRIVER=redis</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Enable caching for a module in config/modularous.php (or modularity.php)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># See Configuration and Per-Module Setup pages</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Add HasCaching to the entity model</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># use Unusualify\\Modularous\\Entities\\Traits\\Core\\HasCaching;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Rebuild the relationship graph after enabling new modules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:cache:graph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebuild</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. Pre-warm caches (optional, recommended after deploy)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:cache:warm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PressRelease</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PressRelease</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --counts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --formattedItems</span></span></code></pre></div><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Enable module-route cache when:</p><ul><li>Admin index pages or filter badges are slow under production data volume</li><li>Form edit payloads (<code>formItem</code>) or table row formatting (<code>formattedItem</code>) are expensive to build</li><li>Related models (payments, packages, companies) should invalidate dependent admin routes automatically</li></ul><p>Skip or narrow cache types when data changes every few seconds and stale UI is unacceptable — use shorter TTLs or disable specific types per route instead of turning off the whole system.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/system-reference/backend/services/modularous-cache-service">ModularousCacheService</a> — service internals</li><li><a href="/system-reference/backend/services/cache-relationship-graph">CacheRelationshipGraph</a> — auto-discovery graph</li><li><a href="./../console/cache/overview">Cache Commands</a> — clear, warm, stats, graph</li></ul>`,13),n=[r];function d(o,l,c,h,p,u){return s(),a("div",null,n)}const k=e(i,[["render",d]]);export{g as __pageData,k as default};
